/** By Leetcode */
var numOfWays = function (nums) {
    const MOD = 1_000_000_007n;
    const n = nums.length;

    const dp = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0n));
    for (let i = 0; i <= n; i++) {
        dp[i][0] = 1n;

        for (let j = 1; j <= i; j++) {
            dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) % MOD;
        }
    }

    const dfs = (arr) => {
        const m = arr.length;
        if (m <= 2) return 1n;

        const left = [];
        const right = [];

        for (let i = 1; i < m; i++) {
            if (arr[i] < arr[0]) left.push(arr[i]);
            else right.push(arr[i]);
        }

        return dp[m - 1][left.length] * dfs(left) % MOD * dfs(right) % MOD;
    };

    return Number((dfs(nums) - 1n + MOD) % MOD);
};
